      sealTitle.id = 'sealPanelTitle'; // fixed id, same as #machinesTitle: the dialog is built fresh
      sealPanel.setAttribute('role', 'group');          // and removed on close, and textContent=''
      sealPanel.setAttribute('aria-labelledby', sealTitle.id); // above clears any previous heading
