      // before the rows below because the cap-check closures need it; appended to the DOM later,
      // right above the confirm button, per the brief's own layout.
      const sealError = el('p', 'seal-error'); sealError.setAttribute('role', 'alert'); sealError.hidden = true;

      const portsWrap = el('div', 'sealports'); sealPanel.appendChild(portsWrap);
      const offers = Brick.offerablePorts(state.table, state.table.pieces.map((p) => p.id), { connsFor: (p) => connsOf(p, state.table) });
      // The word for an offer's own END (whole-branch review, finding 1): portLabel is the
      // SIGNAL-side rule and itemEndWord is the ITEM-side rule (both now brick-aware) — neither
      // alone is right for every offer this chooser lists, so this dispatches on the offer's own
      // plane instead of hand-rolling a THIRD copy of either rule.
      const wordFor = (o) => (o.plane === 'item' ? itemEndWord(o.end, o.type) : portLabel(o.end, o.piece));
      const rows = []; // {checkbox, nameInput, offer} — read at confirm time
