        const checkbox = el('input'); checkbox.type = 'checkbox';
        check.append(checkbox, el('span', '', wordFor(o)));
        row.appendChild(check);
        // Spec §4 item 2: a plain sentence for what this end carries, alongside the block's own
        // name (the group header above) plus the end's own name (the checkbox label above).
        row.appendChild(el('p', 'sealwhat hint', t('seal.carries.' + o.plane + '.' + o.dir)));
        const socketDesc = [o.pieceName || t('block.' + o.type), wordFor(o)].join(' ');
        const portNameInput = el('input'); portNameInput.type = 'text'; portNameInput.maxLength = 24;
        // The default name is the owning block's own name and the end — never a bare 'in'/'in2':
        // the name is the only thing the sealed part's face shows on the floor (brief's own law).
        portNameInput.value = [o.pieceName || t('block.' + o.type), wordFor(o)].join(' ').trim().slice(0, 24);
        // fix round 1, CRITICAL: this field was orphaned — no <label>, no aria-label, no
