    if (row.outcome && row.outcome.status === 'answered') box.appendChild(el('p', '', t('batch.guess', { value: String(row.outcome.guess) })));
    if (row.outcome && Number.isFinite(row.outcome.error)) box.appendChild(el('p', 'batchnumeric', t('batch.numeric', { error: row.outcome.error, tolerance: row.outcome.tolerance })));
